import React, { useState } from 'react';
import './LoginScreen.css';

const LoginScreen = ({ onLogin, onRegister, isLoading }) => {
  const [isLoginMode, setIsLoginMode] = useState(true);
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    terminal_color: '#00FF00'
  });
  const [error, setError] = useState('');

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!isLoginMode && formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    try {
      if (isLoginMode) {
        await onLogin({
          username: formData.username,
          password: formData.password
        });
      } else {
        await onRegister({
          username: formData.username,
          email: formData.email,
          password: formData.password,
          terminal_color: formData.terminal_color
        });
      }
    } catch (err) {
      setError(err.message || 'An error occurred');
    }
  };

  const colorOptions = [
    { value: '#00FF00', label: 'Green', class: 'green' },
    { value: '#00FFFF', label: 'Cyan', class: 'blue' },
    { value: '#FFB900', label: 'Amber', class: 'amber' },
    { value: '#FF00FF', label: 'Magenta', class: 'purple' },
    { value: '#FF0000', label: 'Red', class: 'red' },
    { value: '#FFFF00', label: 'Yellow', class: 'yellow' }
  ];

  return (
    <div className="login-screen">
      <div className="login-container">
        <h1 className="login-title terminal-text">
          VOXA CLI
        </h1>

        <div className="login-tabs">
          <button
            className={`login-tab ${isLoginMode ? 'active' : ''}`}
            onClick={() => setIsLoginMode(true)}
          >
            Login
          </button>
          <button
            className={`login-tab ${!isLoginMode ? 'active' : ''}`}
            onClick={() => setIsLoginMode(false)}
          >
            Register
          </button>
        </div>

        <form className="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label className="form-label">Username</label>
            <input
              type="text"
              name="username"
              className="form-input"
              value={formData.username}
              onChange={handleInputChange}
              required
              placeholder="Enter your username"
            />
          </div>

          {!isLoginMode && (
            <div className="form-group">
              <label className="form-label">Email</label>
              <input
                type="email"
                name="email"
                className="form-input"
                value={formData.email}
                onChange={handleInputChange}
                required
                placeholder="Enter your email"
              />
            </div>
          )}

          <div className="form-group">
            <label className="form-label">Password</label>
            <input
              type="password"
              name="password"
              className="form-input"
              value={formData.password}
              onChange={handleInputChange}
              required
              placeholder="Enter your password"
            />
          </div>

          {!isLoginMode && (
            <>
              <div className="form-group">
                <label className="form-label">Confirm Password</label>
                <input
                  type="password"
                  name="confirmPassword"
                  className="form-input"
                  value={formData.confirmPassword}
                  onChange={handleInputChange}
                  required
                  placeholder="Confirm your password"
                />
              </div>

              <div className="form-group">
                <label className="form-label">Terminal Color</label>
                <div className="color-picker">
                  {colorOptions.map(color => (
                    <label key={color.value} className="color-option">
                      <input
                        type="radio"
                        name="terminal_color"
                        value={color.value}
                        checked={formData.terminal_color === color.value}
                        onChange={handleInputChange}
                      />
                      <span className={`color-preview ${color.class}`}></span>
                      <span className="color-label">{color.label}</span>
                    </label>
                  ))}
                </div>
              </div>
            </>
          )}

          {error && (
            <div className="error-message">
              {error}
            </div>
          )}

          <button
            type="submit"
            className="btn primary"
            disabled={isLoading}
          >
            {isLoading ? 'Processing...' : (isLoginMode ? 'Login' : 'Register')}
          </button>
        </form>

        <div className="login-footer">
          <p className="terminal-text">
            Welcome to Voxa CLI - Your Voice-Enabled Smart Assistant
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginScreen;
